<?php use App\Core\View; use App\Core\Env; $baseUrl=rtrim((string)Env::get('APP_URL',''),'/'); $flowIndex=array_search($delivery['status'],App\Models\Delivery::FLOW,true);$totalWeight=array_sum(array_map(function($g){return(float)$g['quantity']*(float)($g['unit_weight_kg']??0);},$delivery['goods']));$currentDestination=$delivery['current_destination'];$delivery['site_name']=$delivery['destination_count'].' destination(s)';$delivery['site_city']=$currentDestination?'Prochain arrêt : '.$currentDestination['label']:'Itinéraire terminé'; ?>
