<section class="workflow-panel panel"><div class="workflow-head"><div><h2>Progression de la livraison</h2><p>Dernière mise à jour le <?= date('d/m/Y à H:i',strtotime($delivery['updated_at'])) ?></p></div><?php if($canTransition&&$allowedNext): ?><div class="workflow-actions"><?php foreach($allowedNext as $next): ?><button class="button <?= in_array($next,['Incident','Annulée'],true)?'button-secondary':'button-primary' ?>" data-transition-status="<?= htmlspecialchars($next,ENT_QUOTES,'UTF-8') ?>"><?= $next==='Incident'?'<i data-lucide="triangle-alert"></i>':($next==='Annulée'?'<i data-lucide="x-circle"></i>':'<i data-lucide="arrow-right"></i>') ?> <?= htmlspecialchars($next,ENT_QUOTES,'UTF-8') ?></button><?php endforeach; ?></div><?php endif; ?></div><div class="workflow-track"><?php foreach(App\Models\Delivery::FLOW as $index=>$status): ?><?php $complete=$flowIndex!==false&&$index<$flowIndex;$active=$delivery['status']===$status; ?><div class="workflow-step <?= $complete?'complete':'' ?> <?= $active?'active':'' ?>"><span><?= $complete?'<i data-lucide="check"></i>':($index+1) ?></span><small><?= htmlspecialchars($status,ENT_QUOTES,'UTF-8') ?></small></div><?php endforeach; ?></div><?php if($delivery['status']==='Incident'): ?><div class="incident-banner"><i data-lucide="triangle-alert"></i><div><strong>Livraison en incident</strong><p>Le workflow est suspendu. Une reprise vers <?= htmlspecialchars($delivery['status_before_incident']??'le statut précédent',ENT_QUOTES,'UTF-8') ?> est possible après résolution.</p></div></div><?php endif; ?></section>
