trong><?= htmlspecialchars($delivery['registration_number']?:'Non affecté',ENT_QUOTES,'UTF-8') ?></strong><p><?= htmlspecialchars(trim(($delivery['vehicle_brand']??'').' '.($delivery['vehicle_model']??'')),ENT_QUOTES,'UTF-8') ?></p></div></div></article><article class="panel delivery-summary-card"><div><strong><?= (int)$delivery['destination_count'] ?></strong><span>Destinations</span></div><div><strong><?= count($delivery['goods']) ?></strong><span>Marchandises</span></div><div><strong><?= number_format($totalWeight,1,',',' ') ?> kg</strong><span>Poids estimé</span></div></article></section>
