r_format((float)$destination['total_weight_kg'],1,',',' ') ?> kg estimés</p></div></div><div class="destination-goods"><div class="destination-goods-head"><strong>Marchandises à remettre</strong><span><?= (int)$destination['goods_count'] ?> ligne(s)</span></div><?php if(!$destination['goods']): ?><p class="destination-goods-empty">Aucune marchandise rattachée à cet arrêt.</p><?php else: ?><div class="destination-goods-list"><?php foreach($destination['goods'] as $goods): $condition=$goods['delivery_condition']??null;$isAnomaly=$condition&&$condition!=='Conforme'; ?><div class="destination-goods-row <?= $isAnomaly?'has-anomaly':'' ?>"><div><strong><?= htmlspecialchars($goods['description_snapshot'],ENT_QUOTES,'UTF-8') ?></strong><small><?= htmlspecialchars($goods['reference']?:'Sans référence catalogue',ENT_QUOTES,'UTF-8') ?></small></div><span><b><?= htmlspecialchars($goods['quantity'].' '.$goods['unit'],ENT_QUOTES,'UTF-8') ?></b><small>Prévu</small></span><span><b><?= $goods['unit_weight_kg']?number_format((float)$goods['quantity']*(float)$goods['unit_weight_kg'],1,',',' ').' kg':'—' ?></b><small>Poids</small></span><div class="goods-control-state"><?php if($condition): ?><b class="<?= $isAnomaly?'anomaly':'conform' ?>"><?= htmlspecialchars($condition,ENT_QUOTES,'UTF-8') ?></b><small><?= htmlspecialchars(($goods['delivered_quantity']??0).' '.$goods['unit'].' remis',ENT_QUOTES,'UTF-8') ?></small><?php if($goods['driver_note']): ?><em><?= htmlspecialchars($goods['driver_note'],ENT_QUOTES,'UTF-8') ?></em><?php endif; ?><?php else: ?><b class="waiting">À contrôler</b><small>Par le chauffeur</small><?php endif; ?></div></div><?php endforeach; ?></div><?php endif; ?></div><?php if($destination['pod_id']): ?><footer class="destination-pod"><span><i data-lucide="badge-check"></i></span><div><small>PREUVE DE LIVRAISON</small><strong><?= htmlspecialchars($destination['recipient_name'],ENT_QUOTES,'UTF-8') ?></strong><p><?= date('d/m/Y à H:i',strtotime($destination['pod_captured_at'])) ?></p></div><a class="button button-secondary" href="<?= $baseUrl ?>/deliveries/<?= (int)$delivery['id'] ?>/destinations/<?= (int)$destination['id'] ?>/pod.pdf" target="_blank"><i data-lucide="file-down"></i> PDF</a></footer><?php endif; ?></article><?php endforeach; ?><?php if($delivery['general_goods']): ?><article class="panel destination-detail-card general-goods-card"><header><span class="destination-number"><i data-lucide="package"></i></span><div><small>COMPATIBILITÉ ANCIENNES DONNÉES</small><h3>Marchandises générales</h3><p>Ces lignes ne sont rattachées à aucune destination précise.</p></div></header><div class="destination-goods-list"><?php foreach($delivery['general_goods'] as $goods): ?><div class="destination-goods-row"><div><strong><?= htmlspecialchars($goods['description_snapshot'],ENT_QUOTES,'UTF-8') ?></strong></div><span><b><?= htmlspecialchars($goods['quantity'].' '.$goods['unit'],ENT_QUOTES,'UTF-8') ?></b><small>Prévu</small></span></div><?php endforeach; ?></div></article><?php endif; ?></div></section>
